import { writingItem } from './coachedTaskHelpers'
import type { WritingCase } from './coachedTaskHelpers'

const emails: WritingCase[] = [
  { topic: '도서관 예약 변경', prompt: 'You reserved a library group room for Thursday at 3 p.m., but your team’s required workshop now ends at 3:30. Write to the library booking desk. Explain the conflict, request a later room for four people, and ask what to do if no room is available.', checklist: ['목요일 3시 예약과 워크숍 종료 시각의 충돌 설명', '4명이 사용할 늦은 시간의 방 요청', '빈 방이 없을 때 가능한 대안 문의'], model: 'Dear Library Booking Team,\nI am writing about our group-room reservation for Thursday at 3 p.m. Our department has moved a required workshop, and it will now finish at 3:30, so our four-person team cannot arrive at the reserved time. Would it be possible to move the booking to 4 p.m. or another available time later that afternoon? We need a space where we can discuss our project and review slides together. If all group rooms are occupied, could you suggest another suitable area or explain whether we should cancel and join a waiting list? I will confirm the team’s availability as soon as I hear from you. Thank you for your help.\nBest regards,\nAlex', mistakes: ['워크숍이 끝나기 전에 방을 사용할 수 있다고 쓰기', '인원이나 원하는 변경 시간을 빠뜨리기', '예약 변경이 이미 승인됐다고 단정하기'], rewrite: '4시 이외에 팀이 실제로 가능한 시간 두 개를 제시하는 버전으로 바꾸세요.' },
  { topic: '수업 자료 접근', prompt: 'The audio on this week’s course video is difficult to understand, and the captions are missing. Write to your instructor. Describe the problem, explain its effect on your preparation, and request an accessible alternative before Friday’s seminar.', checklist: ['음성과 자막의 구체적인 문제 설명', '금요일 세미나 준비에 미치는 영향', '자막·대본 등 이용 가능한 대안 요청'], model: 'Dear Professor Chen,\nI am having difficulty using the video assigned for Friday’s seminar. The audio becomes very quiet during the second half, and I cannot find captions in the player. I have tried listening with headphones, but I still miss several points that we are expected to discuss. This makes it difficult to prepare a reliable summary and choose a question for class. Could you provide a transcript, a captioned version, or another source covering the same ideas? If an updated file will take time, guidance on which reading sections to review would also help. I would appreciate having an alternative before Friday so I can participate fully. Thank you for considering the request.\nBest regards,\nJordan', mistakes: ['내용이 어려운 문제와 음성 접근 문제를 혼동하기', '접근 가능한 자료 대신 과제 면제를 당연하게 요구하기', '자료를 받아야 할 시점을 생략하기'], rewrite: '문제가 시작되는 정확한 위치를 넣고, 가장 도움이 되는 대안을 하나 우선 요청하세요.' },
  { topic: '동아리 행사 공간', prompt: 'Your student club planned an outdoor welcome event, but rain is forecast. Write to the student activities office. Explain the event and expected attendance, request an indoor space, and ask about equipment or booking conditions.', checklist: ['환영 행사와 예상 참가 인원 소개', '우천에 대비한 실내 공간 요청', '장비 또는 예약 조건 문의'], model: 'Dear Student Activities Office,\nOur photography club is planning a welcome event for about twenty-five students on Saturday afternoon. We originally intended to meet in the courtyard, but the forecast now suggests rain. Could we reserve an indoor room from 2 to 4 p.m. so the event can go ahead? Participants will introduce themselves and share a few photographs, so a projector would be useful, although we can bring our own laptop. Please let us know whether a suitable room is available and whether we need to submit a revised event form or pay any equipment fee. We can adjust the layout to meet room rules and will leave the space clean afterward. Thank you for helping us prepare an alternative.\nBest regards,\nSam', mistakes: ['우천 예보를 행사 취소 확정으로 바꾸기', '필요 장비가 무료라고 가정하기', '행사 규모를 생략하기'], rewrite: '프로젝터가 없어도 진행할 수 있는 방안을 한 문장 추가하세요.' },
  { topic: '기숙사 공용 주방', prompt: 'The shared kitchen in your residence has repeatedly been left dirty after evening use. Write to the residence coordinator. Give a specific example, explain the effect on residents, and propose a practical way to improve the situation.', checklist: ['저녁 이용 후 반복되는 청소 문제의 구체적 예', '다른 거주자에게 생기는 불편', '실행 가능한 개선책 제안'], model: 'Dear Residence Coordinator,\nI would like to raise a concern about the shared kitchen on our floor. On three evenings this week, food was left on the counters and several pans remained in the sink overnight. Residents who arrived later could not prepare meals without first cleaning up, and the space was still unpleasant the next morning. Could we introduce a clear cleanup checklist near the door and remind residents to finish cleaning before leaving? A brief message to everyone might help without singling out individuals we cannot reliably identify. If the problem continues, a regular check at the end of the evening could show whether the reminder is working. I would be happy to help draft the checklist.\nBest regards,\nTaylor', mistakes: ['확인하지 않은 특정 거주자를 비난하기', '불편만 설명하고 개선책을 제시하지 않기', '청소 문제가 해결됐다고 미리 결론짓기'], rewrite: '체크리스트에 들어갈 구체적인 청소 행동 두 가지를 써 보세요.' },
  { topic: '인턴십 면접 일정', prompt: 'You have an internship interview at the same time as a compulsory examination. Write to the internship coordinator. Explain the conflict, offer two alternative times, and express your continuing interest in the position.', checklist: ['필수 시험과 면접 시간의 충돌 설명', '대체 시간 두 개 제시', '인턴십에 대한 관심과 일정 확인 요청'], model: 'Dear Internship Coordinator,\nThank you for inviting me to interview for the campus sustainability internship. I am very interested in the position, especially the opportunity to support student projects. Unfortunately, the proposed interview on Tuesday at 10 a.m. overlaps with a compulsory examination that I cannot reschedule. Would it be possible to meet on Tuesday after 2 p.m. or on Wednesday between 9 and 11 a.m.? I can attend either in person or online if that makes arranging a new time easier. I understand that you are coordinating several candidates, so please let me know if a different slot would be more convenient. I will respond promptly and provide any further information you need. Thank you for your flexibility.\nBest regards,\nMorgan', mistakes: ['면접에 관심이 없다는 인상을 주는 짧은 취소 통보', '가능한 시간 없이 변경만 요청하기', '필수 시험을 옮길 수 있다고 가정하기'], rewrite: '대체 시간에 시간대를 포함하고, 온라인 면접이 가능한 조건을 덧붙이세요.' },
  { topic: '동료 과제 분담', prompt: 'A group project deadline is approaching, but one part of the work has not been submitted. Write to the group member responsible. Ask about progress, explain what the group needs next, and suggest a plan if they need help.', checklist: ['미제출 부분의 진행 상태 질문', '다음 작업과 내부 마감 설명', '도움이 필요한 경우의 협력 방안 제안'], model: 'Hi Casey,\nI wanted to check how the interview summary is going for our group project. We are putting the report together tomorrow afternoon, and your section will help us connect the results to the discussion. Could you send either the completed summary or a short update by noon tomorrow? If something has made the work harder than expected, please let us know so we can plan around it. I can help organize the notes this evening, and another member may be able to check the wording once a draft is ready. We do not need a perfect first version, but we do need to know what material will be available. Thanks, and please tell me what support would be useful.\nAlex', mistakes: ['진행 상황을 묻지 않고 태만으로 단정하기', '최종 제출 마감과 팀 내부 마감을 혼동하기', '도움 제안 없이 책임만 강조하기'], rewrite: '팀 내부 마감과 최종 마감이 다르다는 점을 한 문장으로 분명히 하세요.' },
  { topic: '운동 수업 대기 명단', prompt: 'You are on the waiting list for a beginner swimming course. Write to the sports center. Confirm your interest, ask how openings are offered, and request another beginner option if the course remains full.', checklist: ['초급 수영 과정 참여 의사 확인', '결원 안내 방식과 응답 기한 문의', '만석일 때 다른 초급 과정 문의'], model: 'Dear Sports Center Team,\nI recently joined the waiting list for the beginner swimming course on Monday evenings and would like to confirm that I am still interested. Could you explain how students are contacted when a place becomes available and how long we have to accept it? I want to make sure I do not miss an offer while I am in class. If this course remains full, I would also appreciate information about another beginner session or a later course with similar instruction. I am free on Wednesday evenings as well as Mondays. Please let me know whether I should stay on the current list while considering other options. Thank you for your guidance.\nBest regards,\nRiley', mistakes: ['대기 명단 등록을 수강 확정으로 표현하기', '결원 통보의 응답 조건을 빠뜨리기', '초급 수준에 맞는 대안을 요청하지 않기'], rewrite: '연락을 놓쳤을 때 자리가 어떻게 처리되는지 묻는 문장을 추가하세요.' },
  { topic: '학생 신문 정정', prompt: 'The student newspaper listed the wrong time for an event you are organizing. Write to the editor. Identify the error, provide the correct time, and request a correction that reaches students who saw the original notice.', checklist: ['잘못 실린 행사 시간 확인', '정확한 날짜·시간 제공', '기존 독자에게도 전달되는 정정 요청'], model: 'Dear Editor,\nThank you for including our volunteer fair in this week’s student newspaper. I noticed that the notice lists the start time as 4 p.m., but the event begins at 2 p.m. on Friday in the student center. Since students may plan their afternoon around the published time, could you correct the online notice and add a brief update through the newspaper’s usual announcement channel? That would help reach people who have already read the original version. The location and date are otherwise correct, so only the start time needs to change. I can send the organizer’s confirmed schedule if you would like to check it before posting the correction. Thank you for helping us prevent confusion.\nBest regards,\nJamie', mistakes: ['잘못된 정보만 지적하고 정확한 시간을 주지 않기', '다른 정보까지 잘못됐다고 과장하기', '온라인 수정만으로 모든 기존 독자에게 전달됐다고 가정하기'], rewrite: '정정 문구를 독자가 바로 이해할 수 있는 한 문장으로 제안하세요.' },
  { topic: '버스 분실물', prompt: 'You left a small bag on a campus bus yesterday. Write to the transport office. Describe the bag and journey, explain how you can identify it, and ask about collection arrangements if it is found.', checklist: ['가방 외형과 탑승 노선·시각 설명', '본인 물건임을 확인할 수 있는 특징', '발견 시 수령 절차 문의'], model: 'Dear Campus Transport Office,\nI think I left a small blue bag on Route 6 yesterday afternoon. I boarded near the library at about 4:10 p.m. and got off at the north residence stop. The bag has a grey strap and a small yellow key ring attached to the zip. Inside, there is a notebook with my first name on the opening page, which I can describe more fully if needed. Could you check whether a driver handed it in or advise me where to report the loss? If it has been found, please let me know the collection hours and whether I should bring student identification. Thank you for your help in locating it.\nBest regards,\nRobin', mistakes: ['개인정보를 과도하게 공개하기', '가방이 발견됐다고 단정하기', '외형만 쓰고 탑승 정보를 빠뜨리기'], rewrite: '이메일에는 민감한 내용물을 나열하지 않고 확인 방법을 제시하는 버전으로 바꾸세요.' },
  { topic: '발표 연습 피드백', prompt: 'You are preparing your first class presentation and want feedback on its organization. Write to your teaching assistant. Describe the presentation, explain which part concerns you, and request a short review or an alternative way to get feedback.', checklist: ['첫 발표의 주제와 형식 설명', '구성이 걱정되는 구체적 부분', '짧은 검토 또는 대체 피드백 방법 요청'], model: 'Dear Teaching Assistant,\nI am preparing my first presentation for the introductory geography class. It will explain how a neighborhood survey was carried out, and I have drafted six slides for a five-minute talk. I am unsure whether the transition from the survey questions to the findings is clear enough for listeners who have not seen our notes. Would you have time to look at the outline briefly during office hours? I would especially value advice on whether the main point appears early enough. If an individual review is not possible, could you recommend a checklist or a peer-feedback activity I can use? I can send the outline if that would help you review the section I mean. Thank you for your guidance.\nBest regards,\nDrew', mistakes: ['검토 대상 없이 발표 전체를 대신 만들어 달라고 요청하기', '피드백 받고 싶은 부분을 모호하게 쓰기', '첨부하지 않은 자료를 첨부했다고 주장하기'], rewrite: '실제 첨부 여부에 맞춰 마지막 부분을 수정하고, 가장 중요한 피드백 질문 하나를 남기세요.' },
  { topic: '행사 자원봉사 교대', prompt: 'Your volunteer shift now conflicts with a family appointment. Write to the volunteer organizer. Explain the conflict, offer another shift or useful task, and ask how to confirm the change.', checklist: ['기존 봉사 교대와 약속의 충돌', '대체 교대 또는 다른 도움 제안', '변경을 확정하는 방법 문의'], model: 'Dear Volunteer Organizer,\nI am scheduled to help at the information desk from 1 to 3 p.m. on Saturday. A family appointment has now been moved to that time, so I will not be able to cover the full shift. I would still like to contribute to the event. Could I switch to the morning setup team, or help prepare the signs on Friday instead? I am available after 4 p.m. on Friday and before noon on Saturday. Please let me know which option would be most useful and whether I should arrange a replacement through the volunteer system. I will keep the current shift listed until you confirm the change, so the desk is not left uncovered. Thank you for understanding.\nBest regards,\nLee', mistakes: ['새 교대가 확정되기 전에 기존 교대를 취소했다고 쓰기', '도움을 계속하려는 의사를 생략하기', '필요 없는 개인 사정을 길게 나열하기'], rewrite: '주최자가 바로 선택할 수 있도록 대체 방안 두 개를 짧게 정리하세요.' },
  { topic: '캠퍼스 식당 선택지', prompt: 'You often eat at the campus cafeteria, but suitable vegetarian meals sell out early. Write to the dining manager. Describe the situation, explain its effect, and propose an improvement while asking how students can provide feedback.', checklist: ['채식 식사가 일찍 매진되는 상황', '수업 후 식사 선택에 미치는 영향', '개선책과 의견 전달 방법 제안'], model: 'Dear Dining Manager,\nI regularly use the main cafeteria after my afternoon class, but the vegetarian meal has sold out before I arrive on several days this month. When that happens, I can usually buy a side dish, but it is difficult to find a complete meal between classes. Would it be possible to prepare a small second batch or offer a simple vegetarian option that remains available later? I understand that preparing too much food could create waste, so collecting demand information might help you decide what quantity is appropriate. Could you let students know where to send feedback or indicate their usual meal times? I would be happy to contribute to a short survey. Thank you for considering the suggestion.\nBest regards,\nPat', mistakes: ['모든 식단이 채식이어야 한다는 요청으로 바꾸기', '수요를 확인하지 않고 음식을 대량으로 더 만들 것을 요구하기', '매진 사례와 영향을 구체적으로 설명하지 않기'], rewrite: '낭비를 줄이면서 늦은 시간 수요를 확인하는 방법을 하나 구체화하세요.' },
  { topic: '박물관 견학 예약', prompt: 'Your class wants to visit a local museum, but the online form does not show group availability. Write to the museum education office. Describe the class and learning goal, ask about suitable times, and check the group booking requirements.', checklist: ['수업 인원과 견학 학습 목적', '가능한 방문 시간 문의', '단체 예약과 안내 조건 확인'], model: 'Dear Museum Education Team,\nOur first-year history class would like to visit the museum to learn how objects are selected and explained in an exhibition. We expect about twenty students and hope to come on a Tuesday or Thursday morning next month. The online form shows individual tickets, but I could not find information about group availability. Could you suggest a suitable time and let us know whether a short guided introduction is available? We would also appreciate details about booking deadlines, any group charge, and the number of accompanying instructors required. If a guided visit is not possible, we can prepare our own observation questions before arriving. Thank you for helping us plan a useful visit.\nBest regards,\nQuinn', mistakes: ['단체 예약을 개인 티켓 구매와 같다고 가정하기', '박물관이 반드시 무료 안내를 제공한다고 쓰기', '견학의 학습 목적을 생략하기'], rewrite: '해설 없이 방문할 때 학생들이 관찰할 질문 한 가지를 덧붙이세요.' },
  { topic: '프린터 과금 오류', prompt: 'A campus printer charged your account although no pages came out. Write to the printing help desk. Explain what happened, provide information that could help them check it, and request the appropriate correction.', checklist: ['출력 없이 과금된 상황 설명', '장소·시각·작업 내역 제공', '확인 후 적절한 계정 정정 요청'], model: 'Dear Printing Help Desk,\nI would like help checking a printing charge from this morning. At about 9:20, I sent a twelve-page document to the printer beside the library entrance. The screen showed that the job had started, but no pages came out and a paper warning appeared. My account balance was reduced for the full job. Could you check the printer log and advise whether the charge can be corrected? I have saved the job number and can provide it through the support form if needed. I did not send the document again because I wanted to avoid a second charge before the problem was checked. Please let me know if there is another step I should take. Thank you.\nBest regards,\nAvery', mistakes: ['확인 전에 전액 환불이 보장됐다고 쓰기', '작업 정보 없이 오류라고만 주장하기', '로그를 직접 삭제하거나 수정하겠다고 제안하기'], rewrite: '직원에게 확인을 맡기면서 증빙을 어떻게 제공할지 명확하게 써 보세요.' },
  { topic: '연구 참가 일정', prompt: 'You volunteered for a campus study but cannot attend the scheduled session. Write to the study coordinator. Explain your availability, ask whether you can reschedule, and confirm what to do if you decide not to participate.', checklist: ['기존 참가 시간과 새 가능 시간', '재예약 가능 여부 문의', '참가하지 않을 경우 연락 방법 확인'], model: 'Dear Study Coordinator,\nI registered for the study session on Wednesday at 11 a.m., but a required class activity has been added at the same time. I am sorry that I can no longer attend that session. Would it be possible to reschedule for Friday morning or early next week? I remain interested in participating, although I would like to know how long the session will take so I can leave enough time between classes. If no alternative is available, please explain how I should notify the team that I will not take part. I do not want an unused booking to prevent another volunteer from joining. Thank you for your help with the schedule.\nBest regards,\nSky', mistakes: ['자원 참가를 의무 참가처럼 표현하기', '취소 방법을 확인하지 않고 무단 불참을 제안하기', '가능한 시간을 제시하지 않기'], rewrite: '참가 가능 여부를 결정할 때 필요한 정보 한 가지를 추가로 질문하세요.' },
  { topic: '결석 후 학습 계획', prompt: 'You missed a class because of a medical appointment. Write to your instructor. Explain the absence briefly, describe how you plan to catch up, and ask about any in-class work that needs attention.', checklist: ['불필요한 의료 정보 없이 결석 사유 설명', '자료와 노트로 보충할 계획', '수업 중 활동의 처리 방법 문의'], model: 'Dear Professor Rivera,\nI missed Tuesday’s class because I had a medical appointment that could not be moved. I have read the slides on the course site and arranged to compare notes with a classmate, so I can catch up before the next meeting. However, I understand that the class also completed a short group exercise that is not included in the slides. Could you let me know what I should review from that activity and whether there is any work I need to submit? I am not asking you to repeat the whole lesson; I would simply like to make sure that I follow the correct catch-up procedure. Thank you for your guidance.\nBest regards,\nAlex', mistakes: ['결석만 알리고 보충 계획을 쓰지 않기', '확인 없이 모든 활동 면제를 요구하기', '진료의 민감한 세부사항을 길게 설명하기'], rewrite: '이미 완료한 보충 학습과 앞으로 할 일을 시제로 구분해 쓰세요.' },
  { topic: '행사장 접근 경로', prompt: 'You are attending a campus event with a friend who uses a wheelchair, but the invitation mentions only an entrance with steps. Write to the event organizer. Ask about an accessible route, request arrival instructions, and explain why confirming them in advance matters.', checklist: ['계단 없는 접근 경로 문의', '도착 장소와 안내 방법 요청', '사전 확인이 필요한 이유'], model: 'Dear Event Organizer,\nMy friend and I are looking forward to the student film event on Friday. My friend uses a wheelchair, and the invitation appears to direct visitors to an entrance with several steps. Could you confirm whether there is a step-free entrance and a suitable route to the screening room? It would help to know where we should arrive and whether someone will be available to guide us if the route is not clearly marked. We would like to arrange our arrival in advance so that we do not miss the introduction while looking for another entrance. If a map or written directions are available, please send them to us. Thank you for helping us plan our visit.\nBest regards,\nJordan', mistakes: ['이용자의 동의 없이 불필요한 개인 상태를 설명하기', '접근 경로가 있다고 확인 없이 단정하기', '단순한 길 문의에서 도착 안내를 빠뜨리기'], rewrite: '친구에게 도움이 될 안내 방식이 지도인지 문자 설명인지 확인한 뒤 요청을 구체화하세요.' },
  { topic: '여행 지원 예산', prompt: 'You received a small travel grant, but the registration fee has increased since your application. Write to the grant office. Explain the budget change, ask what adjustments are permitted, and offer an updated budget for review.', checklist: ['신청 후 참가비가 오른 상황', '허용되는 예산 변경 문의', '수정 예산 제출과 검토 요청'], model: 'Dear Travel Grant Office,\nThank you for supporting my attendance at the student research meeting. Since I submitted the application, the registration fee has increased, which means my original budget no longer covers the same costs. I would like to ask whether I may adjust the planned amounts for meals and local transport to cover part of the difference. I understand that the grant has conditions, so I will not make that change without checking the rules first. I can send an updated budget showing the new registration fee and the smaller amounts I expect to spend elsewhere. Please let me know which documents you need and whether prior approval is required. Thank you for helping me use the grant correctly.\nBest regards,\nSam', mistakes: ['지원금이 자동으로 늘어난다고 기대하기', '승인 없이 예산 항목을 옮겼다고 쓰기', '비용 변경의 근거를 생략하기'], rewrite: '추가 지원을 요구하는 대신 기존 금액 안에서 가능한 조정을 설명하세요.' },
  { topic: '교환학생 생활 질문', prompt: 'You will join an exchange program next term. Write to the student buddy assigned to you. Introduce yourself, ask two practical questions about campus life, and suggest a convenient way to keep in touch before arrival.', checklist: ['자기소개와 도착 예정 소개', '캠퍼스 생활에 관한 질문 두 개', '도착 전 연락 방법 제안'], model: 'Hi Mia,\nMy name is Taylor, and I will be joining your university as an exchange student next term. Thank you for agreeing to be my student buddy. I am excited about meeting new people, but I still have a few practical questions. First, what is the easiest way to travel from the residence area to morning classes? Second, is there a good place on campus to buy basic household items during the first week? I have checked the university information pages, but a student’s experience would be very helpful. Could we keep in touch by email before I arrive? If you prefer, we could also arrange a short online call at a time that suits you. Thanks again, and I look forward to meeting you.\nTaylor', mistakes: ['질문을 너무 많이 한꺼번에 나열하기', '상대가 늘 즉시 답변할 수 있다고 기대하기', '자기소개 없이 생활 정보를 요청하기'], rewrite: '웹사이트에서 이미 확인한 정보와 아직 궁금한 내용을 구분해 쓰세요.' },
  { topic: '강의실 온도 문제', prompt: 'Your evening classroom has been unusually cold for several weeks. Write to the facilities office. Describe when and where the problem occurs, explain its effect, and ask for an inspection while suggesting a temporary arrangement.', checklist: ['강의실과 문제가 생기는 시간', '학습에 미치는 구체적인 영향', '시설 점검과 임시 대안 요청'], model: 'Dear Facilities Office,\nI am writing about Room 204 in the west teaching building, where our class meets on Tuesday evenings. The room has felt unusually cold during the last three sessions, even though the heating display appears to be on. Several students have kept their coats on throughout the lesson, and it becomes difficult to concentrate during longer activities. Could someone inspect the heating before our next class? We do not know whether the problem is with the settings or the equipment. If it cannot be resolved soon, could you advise our instructor about another available room? We can provide the class time or help arrange access for a check. Thank you for looking into the issue.\nBest regards,\nMorgan', mistakes: ['점검 없이 장비 고장 원인을 단정하기', '건물 전체에 문제가 있다고 과장하기', '문제가 발생하는 시간과 장소를 빠뜨리기'], rewrite: '실제로 관찰한 사실과 점검이 필요한 추정을 서로 다른 문장으로 쓰세요.' },
  { topic: '도서 구입 제안', prompt: 'You need a recent book for a class project, but the university library does not own it. Write to the librarian. Explain why the book is useful, ask whether it can be purchased or borrowed elsewhere, and mention your project timeline.', checklist: ['프로젝트와 책의 관련성 설명', '구입 또는 다른 도서관 대출 가능 여부', '필요한 시점과 대안 문의'], model: 'Dear Librarian,\nI am working on a class project about how local parks are designed for different users. A recent book recommended by our instructor would help us compare several examples, but I could not find it in the library catalog. Could you advise whether the library might purchase a copy or obtain it through a loan from another institution? Our project is due in three weeks, so I would appreciate an estimate of how long either option could take. If the book cannot arrive in time, a related title or an available electronic resource would also be useful. I can send the full title, author, and publication details through the request form. Thank you for your advice.\nBest regards,\nRiley', mistakes: ['책 제목이나 서지 정보를 제공할 방법을 빠뜨리기', '구입이 즉시 승인될 것이라고 가정하기', '마감만 강조하고 책이 필요한 이유를 쓰지 않기'], rewrite: '구입이 어려울 때 어떤 주제의 대체 자료가 유용한지 더 구체적으로 적으세요.' },
  { topic: '등록금 납부 절차', prompt: 'A delayed payment from your scholarship provider may affect your fee deadline. Write to the student accounts office. Explain the situation, ask about available payment arrangements, and offer documentation without assuming an extension is approved.', checklist: ['장학금 입금 지연과 납부 기한의 관계', '가능한 납부 절차 또는 분할 문의', '증빙 제출과 승인 필요성 확인'], model: 'Dear Student Accounts Office,\nMy scholarship provider has informed me that this term’s payment may arrive later than expected. I am concerned that it could reach my account after the university fee deadline. Could you explain whether any temporary payment arrangement or installment option is available in this situation? I would also like to know if I should submit evidence of the expected payment before the deadline. The provider can issue a letter, but I understand that this does not automatically change my obligations to the university. Please let me know the correct steps so I can avoid leaving the matter unresolved. I can provide the relevant documents through a secure channel. Thank you for your guidance.\nBest regards,\nJamie', mistakes: ['장학금 예정 입금을 이미 받은 돈처럼 쓰기', '자동 납부 연장이 승인됐다고 표현하기', '민감한 계좌 정보를 일반 이메일에 넣기'], rewrite: '확정된 사실과 아직 예상인 지급 일정을 표현에서 구분하세요.' },
  { topic: '학생 작품 전시 허가', prompt: 'Your class wants to display student photographs in a campus hallway. Write to the building manager. Describe the display, ask about permission and mounting rules, and explain how you will remove it afterward.', checklist: ['전시 내용과 기간 소개', '허가와 부착 방식 규정 문의', '전시 종료 후 철거 계획'], model: 'Dear Building Manager,\nOur visual communication class would like to display twelve student photographs in the hallway outside our classroom for one week. The work explores everyday campus spaces, and we hope other students will enjoy seeing it. Could you let us know whether a temporary display is permitted there and what approval process we should follow? We also need advice on suitable mounting materials, since we do not want to damage the wall or obstruct signs and walkways. If the hallway is unsuitable, we would appreciate a suggestion for another display area. Our group will label the work, check the display during the week, and remove everything at the agreed time. Thank you for considering our request.\nBest regards,\nRobin', mistakes: ['허가 전에 작품을 설치했다고 쓰기', '통행이나 안내 표지의 방해 가능성을 무시하기', '철거 책임과 일정을 빠뜨리기'], rewrite: '전시 장소가 바뀌어도 유지할 수 있는 계획을 한 문장 제안하세요.' },
  { topic: '실험실 입문 교육', prompt: 'You are joining a laboratory course and missed the first equipment orientation. Write to the laboratory instructor. Explain the situation, request training before using the equipment, and ask what preparation you can complete meanwhile.', checklist: ['장비 교육을 놓친 상황 설명', '장비 사용 전 교육 요청', '교육 전 할 수 있는 준비 문의'], model: 'Dear Laboratory Instructor,\nI recently transferred into the introductory materials course and missed the first equipment orientation. I have read the general laboratory rules, but I have not yet been shown how to use the equipment safely. Could you arrange a make-up orientation or let me know which supervised session I should attend before taking part in practical work? In the meantime, I would be happy to complete the required reading or an online safety activity if one is available. I will not assume that reading the rules qualifies me to operate the equipment independently. Please let me know how to record completion of the training so that I follow the same process as the other students. Thank you for your help.\nBest regards,\nDrew', mistakes: ['안내문을 읽었으니 장비 사용이 가능하다고 주장하기', '교육 없이 친구에게 조작법만 묻겠다고 제안하기', '교육 완료 확인 방법을 생략하기'], rewrite: '교육을 기다리는 동안 수행할 수 있는 비장비 작업을 하나 제안하세요.' },
  { topic: '교재 이용 대안', prompt: 'The required textbook is temporarily unavailable from the campus shop. Write to your instructor. Explain the problem, ask what materials to use for the next class, and inquire about a permitted temporary access option.', checklist: ['필수 교재의 일시적 품절 설명', '다음 수업 준비 자료 문의', '허용되는 임시 접근 방법 확인'], model: 'Dear Professor Adams,\nI tried to buy the required textbook at the campus shop, but staff said the next delivery has been delayed. I have also checked the library catalog and could not find an available copy to borrow before our next class. Could you advise which material I should use to prepare for the discussion while I wait for the book? If there is a permitted electronic option, a short excerpt on the course site, or a suitable alternative reading, I would appreciate the details. I do not want to arrive without completing the preparation, but I also want to use the materials through the proper access arrangements. Thank you for helping me keep up with the course.\nBest regards,\nLee', mistakes: ['허가되지 않은 복사본을 요청하기', '교재가 없으므로 준비할 필요가 없다고 쓰기', '필요 시점과 이미 확인한 경로를 생략하기'], rewrite: '교재 접근 문제와 과제 수행 의사를 함께 보여 주는 첫 문장을 써 보세요.' },
  { topic: '음악 연습실 소음', prompt: 'Sound from a nearby rehearsal room is disturbing a quiet study area. Write to the student center manager. Describe the times and effect, acknowledge the musicians’ need to practice, and propose a workable arrangement.', checklist: ['소음이 발생하는 시간과 영향', '연습 공간의 필요성 인정', '양쪽을 고려한 실행 가능한 조정 제안'], model: 'Dear Student Center Manager,\nI often study in the quiet area on the second floor during the early evening. Recently, sound from the nearby rehearsal room has been loud enough to make reading difficult, particularly between 6 and 7 p.m. I understand that student musicians need a place to practice, and I do not want their sessions to be canceled. Could the doors be checked, or could the loudest rehearsals be scheduled at a time when the quiet area is less busy? Another possibility would be to direct quiet study to a room farther from the rehearsal space during those hours. Please let us know what arrangement is feasible. Thank you for considering the needs of both groups.\nBest regards,\nPat', mistakes: ['연습 자체를 금지해야 한다고 단정하기', '발생 시간 없이 항상 시끄럽다고 과장하기', '한쪽 이용자만 고려하는 해결책'], rewrite: '시설 조치와 시간 조정 중 어떤 방안을 우선 검토할지 이유와 함께 제안하세요.' },
  { topic: '튜터링 배정 조정', prompt: 'Your assigned tutoring session overlaps with your new timetable. Write to the tutoring service. Explain your subject and scheduling needs, request another session, and ask about self-study support while waiting.', checklist: ['과목과 새 시간표의 충돌 설명', '가능 시간에 맞는 다른 세션 요청', '대기 중 자습 지원 자료 문의'], model: 'Dear Tutoring Service,\nI have been assigned a statistics tutoring session on Wednesday at 2 p.m., but my updated timetable now includes a compulsory class at that time. I would like to continue receiving support, especially with interpreting graphs and explaining calculations. Is there another session on Monday afternoon or Thursday morning that I could join? I understand that tutor availability may be limited, so I am also willing to wait for a suitable opening. While I wait, could you recommend practice materials or a drop-in support session? I would prefer not to lose progress simply because of the timetable change. Please let me know whether I should keep my current booking until an alternative is confirmed. Thank you.\nBest regards,\nQuinn', mistakes: ['시간 변경만 말하고 필요한 학습 지원을 생략하기', '대체 시간이 자동 배정된 것처럼 표현하기', '기존 예약 처리 방법을 확인하지 않기'], rewrite: '가장 도움이 필요한 통계 과제를 구체적으로 설명하는 문장을 추가하세요.' },
  { topic: '언어 교류 모임 초대', prompt: 'You are organizing a small language exchange and want another student club to join. Write to its organizer. Explain the format, describe how both groups could participate, and ask about interest and availability.', checklist: ['언어 교류 모임의 형식과 목적', '두 동아리의 참여 방식', '참여 의사와 가능한 시간 문의'], model: 'Hi Club Organizer,\nOur language club is planning a small exchange session and would like to invite your group to take part. We hope to meet for one hour, with students working in pairs and switching languages halfway through. The aim is relaxed conversation rather than a formal lesson, so participants can share everyday interests without preparing a presentation. Your members could help choose a few discussion topics, and our group could arrange the room and simple conversation cards. Would this be of interest to you? We are considering Friday afternoon, but we could explore another time if it suits more people. Please let us know how many members might join and whether you have any suggestions for the format. Thanks for considering it.\nJamie', mistakes: ['상대 동아리의 참여가 확정됐다고 쓰기', '언어 교류를 일방적인 수업으로 설명하기', '형식 설명 없이 초대만 하기'], rewrite: '초보자도 참여하기 쉬운 진행 규칙을 한 가지 덧붙이세요.' },
  { topic: '캠퍼스 정원 물주기', prompt: 'Your student garden team will be away during a holiday week. Write to the grounds office. Explain the plants’ needs, ask whether temporary watering support is possible, and propose how to coordinate responsibilities.', checklist: ['휴일 기간과 필요한 정원 관리', '임시 물주기 지원 가능 여부', '담당·기록·인계 방식 제안'], model: 'Dear Grounds Office,\nOur student garden team will be away during the holiday week, and we are trying to arrange care for the small vegetable beds beside the residence hall. The plants may need watering if there is little rain, but we do not want to interfere with your regular work. Would temporary support be possible, or could you suggest another approved arrangement? We can leave a simple plan showing the beds, the usual checks, and a contact person for questions. A short note after each visit would help us avoid watering twice if a student volunteer is also available. Please let us know what responsibilities we should confirm before leaving. Thank you for considering the request.\nBest regards,\nAvery', mistakes: ['날씨와 무관하게 정해진 양을 강요하기', '시설팀이 반드시 추가 업무를 해야 한다고 쓰기', '학생 봉사자와 시설팀의 중복 작업을 고려하지 않기'], rewrite: '비가 올 때 계획을 어떻게 조정할지 단순한 확인 규칙을 적으세요.' },
  { topic: '대출 도서 분실 문의', prompt: 'You cannot find a library book that is due tomorrow. Write to the lending desk. Explain what you have checked, ask how to report the possible loss, and request information about any next steps or charges.', checklist: ['반납 예정일과 찾아본 상황', '분실 가능성 신고 방법', '다음 절차와 비용 확인'], model: 'Dear Lending Desk,\nI am writing about a book on my account that is due tomorrow. I have checked my room, bag, and the places where I studied this week, but I have not been able to find it. I will continue looking, although I would like to report the possible loss before the deadline. Could you explain the correct procedure and let me know whether I should provide the book details through my account? I would also appreciate information about any replacement or processing charge, and what happens if I find the book after reporting it. I do not want to assume that renewing it will resolve the situation. Thank you for helping me follow the proper steps.\nBest regards,\nSky', mistakes: ['찾아보지 않은 장소까지 확인했다고 쓰기', '대출 연장으로 분실 문제가 해결된다고 가정하기', '비용을 임의로 정하거나 환불을 단정하기'], rewrite: '현재 사실인 분실 가능성과 이후에 책을 찾았을 때의 조건을 구분해 쓰세요.' },
]

const discussions: WritingCase[] = [
  { topic: '강의 출석의 유연성', prompt: 'Professor: Should universities require attendance at every lecture, or let students choose when to attend?', passage: 'Mina: Attendance helps students keep a routine and gives teachers a chance to answer questions.\nOwen: Students have different schedules and may learn more effectively from recordings.', checklist: ['출석 정책에 관한 입장 제시', '학습 방식이나 참여를 설명하는 구체적 예', '다른 학생의 관점을 고려한 조건'], model: 'I would allow some flexibility while requiring attendance for activities that depend on participation. Mina is right that a routine can help, but being physically present does not always mean a student is learning. For example, someone who works an evening shift may understand a lecture better by watching the recording later and completing a short practice task. However, a discussion or group workshop needs people to contribute at the same time. Universities could identify those sessions clearly instead of treating every meeting alike. This approach supports students with different schedules while preserving activities that cannot be recreated simply by playing a video. Teachers would still need a way to notice when students are falling behind.', mistakes: ['출석과 학습 효과를 항상 같다고 단정하기', '녹화 자료만으로 모든 공동 활동을 대체할 수 있다고 쓰기'], rewrite: '유연성을 허용할 수업과 실제 참석이 필요한 수업의 사례를 자신의 경험으로 바꾸세요.' },
  { topic: '도서관 야간 운영', prompt: 'Professor: A university can fund either later library opening hours or more daytime tutoring. Which should receive priority?', passage: 'Nora: Later hours help students who cannot study at home or who work during the day.\nEli: Tutoring addresses learning problems that extra study time alone cannot solve.', checklist: ['우선 투자할 서비스 선택', '예산 선택의 효과를 보여 주는 사례', '선택하지 않은 서비스의 필요성 인정'], model: 'I would give daytime tutoring priority, especially if students are struggling with introductory courses. An extra hour in the library helps only when a student knows how to use that time. A tutor can show someone why a method is not working and suggest a better approach. For instance, a student who repeatedly rereads a difficult chapter may benefit more from learning how to summarize its argument than from simply staying later. Nora’s concern still matters. If an existing evening study room can remain available without diverting this budget, the university should keep it accessible rather than fund longer library hours. Before making a permanent decision, it should compare demand for both services, including students whose work schedules limit daytime access.', mistakes: ['두 서비스를 모두 무제한 확대할 수 있다고 가정하기', '선택 근거 없이 어느 쪽이 더 좋다고만 쓰기'], rewrite: '선택한 서비스가 특히 도움이 되는 학생을 한 유형으로 구체화하세요.' },
  { topic: '세미나의 노트북 사용', prompt: 'Professor: Should instructors allow laptops during small discussion classes?', passage: 'Ada: Laptops make notes searchable and help students consult course materials quickly.\nBen: Screens can distract users and reduce attention to other speakers.', checklist: ['노트북 허용 범위에 대한 입장', '학습 목적과 방해의 구체적 사례', '실행 가능한 수업 규칙 제안'], model: 'Laptops should be allowed for clear learning purposes, with agreed limits during discussion. Ada’s point is useful when students need to find a passage or organize notes. Yet a screen can also make it easy to drift away from the conversation, which affects other students as well as the user. One practical rule would be to close devices during short peer responses and reopen them when the class checks sources. This would keep access to materials without making every activity a screen activity. Instructors should also allow appropriate accessibility tools rather than apply a blanket ban. The goal should be attentive participation, and different students may need different tools to achieve it.', mistakes: ['기기의 존재만으로 참여 수준을 판단하기', '접근성 지원도 예외 없이 금지하기'], rewrite: '어떤 활동에서 기기를 열거나 닫을지 두 가지 구체적인 기준을 써 보세요.' },
  { topic: '팀 과제의 평가', prompt: 'Professor: Should group projects receive one shared grade or separate grades for each member?', passage: 'Sara: A shared grade encourages students to take responsibility for the final team result.\nLuis: Separate grades are fairer when contributions differ.', checklist: ['평가 방식의 입장', '협력과 개인 기여를 함께 설명', '기여를 확인할 현실적인 방법'], model: 'I favor a combination: part of the grade for the team’s result and part for each member’s work. A completely shared grade may hide a serious difference in effort, but entirely separate grades can make students protect their own section instead of helping others. In a research presentation, for example, everyone should care whether the overall argument is clear, while the teacher should also know who collected evidence or revised the slides. Brief progress notes and a final reflection could provide that information. Peer comments may help, but they should not determine the grade alone because friendship or conflict can influence them. A balanced system rewards both contribution and cooperation.', mistakes: ['개인 기여를 결과물의 분량만으로 판단하기', '동료 평가를 객관적 사실처럼 취급하기'], rewrite: '눈에 잘 보이지 않지만 중요한 팀 기여의 사례를 하나 넣으세요.' },
  { topic: '야외 학습 활동', prompt: 'Professor: Should schools use local outdoor spaces more often for learning?', passage: 'Jae: Direct observation makes lessons memorable and connects ideas to real places.\nTess: Travel, weather, and access needs can make outdoor lessons difficult to organize.', checklist: ['야외 학습 확대에 대한 입장', '실내 수업과 연결되는 활동 예', '날씨나 접근 문제에 대한 대응'], model: 'Schools should use outdoor spaces when observation genuinely improves the lesson, rather than treating every visit as a reward. Students studying how public spaces are used could compare seating and walking routes in a nearby park, then discuss their observations in class. That experience gives them evidence they can refer to, which is different from only seeing a diagram. Tess is right about practical limits, so the location should be close, accessible, and supported by a weather alternative. Students who cannot take the same route should still have a meaningful role, such as comparing photographs or recording interviews. Careful planning makes the activity part of the learning goal instead of an interruption to it.', mistakes: ['견학 자체를 학습 효과의 보장으로 쓰기', '참여하기 어려운 학생의 학습 기회를 빠뜨리기'], rewrite: '자신의 전공에서 짧은 현장 관찰이 도움이 되는 주제를 골라 예를 바꾸세요.' },
  { topic: '신입생 멘토링', prompt: 'Professor: Is a student mentor more useful to a newcomer than a detailed university guide?', passage: 'Amir: Mentors can answer personal questions and help newcomers feel connected.\nGrace: A guide provides consistent information without depending on one person’s availability.', checklist: ['멘토와 안내 자료의 관계에 대한 입장', '개별 질문의 예', '잘못된 안내를 막을 방법'], model: 'A mentor is most useful when supported by a reliable guide. Amir is right that a newcomer may need help with questions that feel too small or personal for an official office. A mentor could explain how students usually manage the gap between classes or introduce a club. However, questions about fees or course requirements should be checked against official information, not answered from memory. The guide gives both people a common reference, while the mentor helps the newcomer use it. Universities could train mentors to say when they are unsure and direct students to the right service. This combination offers personal support without making the newcomer depend on one student’s incomplete knowledge.', mistakes: ['멘토 경험을 공식 규정 대신 사용하기', '안내 자료와 사람의 역할을 똑같이 설명하기'], rewrite: '멘토에게 물을 질문과 공식 사무실에 확인할 질문을 각각 하나 제시하세요.' },
  { topic: '구내식당 음식 낭비', prompt: 'Professor: Should cafeterias reduce food waste by serving smaller portions by default?', passage: 'Lina: Smaller initial portions prevent food from being thrown away.\nNoah: Students may still be hungry, and collecting another serving takes time.', checklist: ['기본 분량 조정에 대한 입장', '낭비와 식사 만족을 함께 설명', '추가 제공의 조건 제안'], model: 'Smaller default portions could help if students can easily ask for more. Many people accept the amount they are given even when they do not want all of it, so offering a smaller first serving may reduce leftovers. However, Noah’s concern is important during a short break between classes. A second serving should be available through a quick, clearly marked process rather than a long new queue. The cafeteria could also offer two portion sizes at the start and watch which dishes are frequently left unfinished. That information would be more useful than reducing everything by the same amount. The aim is to match food to appetite, not simply make meals smaller.', mistakes: ['적게 제공하면 모든 낭비가 사라진다고 단정하기', '추가 식사에 필요한 시간과 절차를 무시하기'], rewrite: '분량 조정의 효과를 확인할 수 있는 관찰 자료를 하나 제안하세요.' },
  { topic: '공공 공간의 학생 예술', prompt: 'Professor: Should campus public spaces display more student artwork?', passage: 'Iris: Displays make student creativity visible and encourage conversation.\nMax: Shared spaces should remain easy to navigate and may not suit every type of work.', checklist: ['학생 작품 전시에 대한 입장', '공동 공간에서의 이점 사례', '통행·선정·관리 조건'], model: 'I support student artwork in public spaces when the display is planned around how the space is used. A small exhibition near a cafeteria could introduce work to people who would never visit a gallery and encourage students from different courses to talk. Max is also right that a hallway is not an empty exhibition room. Displays should preserve clear routes, signs, and places to rest, and someone must be responsible for checking and removing them. A rotating selection could give different students a chance without filling every surface permanently. The university should explain how work is chosen so that the display feels open to participation rather than limited to a few well-connected students.', mistakes: ['작품 전시를 위해 통행 안전을 무시하기', '모든 작품을 항상 전시할 수 있다고 가정하기'], rewrite: '전시가 적합한 공간과 적합하지 않은 공간의 차이를 구체적으로 쓰세요.' },
  { topic: '운동 참여 학점', prompt: 'Professor: Should universities offer course credit for regular participation in physical activity?', passage: 'Ken: Credit gives busy students a reason to make time for exercise.\nRose: Required performance standards may exclude students with different abilities.', checklist: ['학점 부여 방식의 입장', '참여 동기를 설명하는 사례', '능력 차이를 고려한 평가 조건'], model: 'Universities could offer optional credit for a course that teaches students to plan suitable physical activity. Ken’s idea may help students protect time for movement, but the grade should not depend on speed, strength, or comparison with classmates. A student could set an appropriate goal, keep a brief activity record, and explain what helped or hindered the plan. Activities might include walking, swimming, or adapted exercise, with advice for students who need it. This would make the course about understanding and sustaining a habit rather than rewarding athletic ability. Students who already exercise should still need to reflect on their choices instead of receiving credit merely for being on a team.', mistakes: ['체력 수준과 학습 성취를 같은 기준으로 평가하기', '모든 학생에게 같은 활동을 요구하기'], rewrite: '성적 기준으로 사용할 학습 행동 두 가지를 제안하세요.' },
  { topic: '공유 자전거 프로그램', prompt: 'Professor: Would a campus bicycle-sharing program be a good use of student transport funds?', passage: 'Eva: Shared bicycles make short trips convenient and reduce demand for parking.\nFinn: Maintenance and safe routes matter more than simply buying bicycles.', checklist: ['교통 예산 사용에 대한 입장', '편리함이 생기는 구체적인 이동 예', '안전과 유지관리의 조건'], model: 'A bicycle-sharing program could be worthwhile where students make frequent short trips along safe routes. For example, bicycles might connect a residence area to a teaching building that is too far for a quick walk but poorly served by buses. However, I agree with Finn that the bicycles alone are not the whole service. Broken equipment, unclear parking, or unsafe crossings would quickly reduce its usefulness. The university should first identify suitable routes and provide maintenance and clear return points. It should also preserve transport options for students who cannot cycle. Starting with a limited service on a well-connected route would show whether there is enough demand before a larger part of the transport budget is committed.', mistakes: ['자전거 구입만으로 서비스가 완성된다고 쓰기', '자전거를 이용할 수 없는 학생을 고려하지 않기'], rewrite: '서비스를 시험해 볼 이동 구간을 자신의 캠퍼스에 맞춰 바꾸세요.' },
  { topic: '빠른 온라인 피드백', prompt: 'Professor: Is immediate automated feedback better than slower feedback from an instructor?', passage: 'Zoe: Fast feedback lets learners correct mistakes while the task is still fresh.\nIan: A teacher can understand a learner’s intention and explain more complex problems.', checklist: ['피드백 방식의 역할 구분', '빠른 피드백이 유용한 사례', '사람의 판단이 필요한 경우'], model: 'The two forms of feedback serve different needs. Immediate feedback is useful for a clear error, such as a missing step in a calculation or an incorrect verb form. A student can try again while remembering the decision that caused it. But an automated comment may misunderstand an unusual argument or suggest a change without explaining why it matters. For a longer essay, an instructor can ask what the writer intended and help connect the evidence to that purpose. I would use quick feedback for early practice and reserve teacher time for problems that require interpretation. Students should also learn to question a suggestion rather than assume that speed makes it correct.', mistakes: ['자동 피드백을 항상 정확하다고 가정하기', '교사의 피드백은 늦기 때문에 모두 쓸모없다고 쓰기'], rewrite: '자신이 받은 피드백 중 즉시 고칠 수 있는 오류와 설명이 필요한 문제를 구분하세요.' },
  { topic: '도심 주차 요금', prompt: 'Professor: Should cities raise parking prices in busy centers to reduce traffic?', passage: 'Hana: Higher prices encourage alternatives and free spaces for people who need them.\nPaul: Some workers have no practical alternative to driving.', checklist: ['주차 요금 정책의 입장', '운전자 행동이 달라지는 이유', '대안이 부족한 이용자에 대한 고려'], model: 'Higher parking prices may help in a busy center, but only if practical alternatives are available. Someone who can reach the area by a frequent bus may choose that option when long parking becomes expensive. A worker who finishes late, however, may have no safe way home without a car. The city should improve service at relevant times and consider carefully defined support for people with genuine access needs. It could also use some parking revenue to fund those improvements. The policy should be evaluated through changes in trips and access, not just the amount collected. Otherwise, it might raise costs without giving people a realistic opportunity to change how they travel.', mistakes: ['가격을 올리면 모든 운전자가 대중교통을 쓴다고 단정하기', '정책 성과를 수입 증가만으로 평가하기'], rewrite: '자동차 외의 이동이 가능한 사람과 어려운 사람의 조건을 한 가지씩 제시하세요.' },
  { topic: '지역 역사와 구술 자료', prompt: 'Professor: Should community history projects give more attention to residents’ personal memories?', passage: 'Dani: Memories reveal everyday experiences that official records may omit.\nJoel: People can forget details or interpret past events differently.', checklist: ['구술 자료의 가치에 대한 입장', '공식 기록에 없는 경험의 예', '기억의 한계를 다룰 방법'], model: 'Residents’ memories deserve a place in community history because they can reveal how change was experienced, not just when it was recorded. A council document may show that a market moved, while interviews explain how the move affected familiar meeting places and daily routines. Joel is right that memory is not a perfect timeline. Researchers should compare accounts with other evidence and distinguish a remembered date from a confirmed one. Differences between memories can also be useful, since residents may have encountered the same change in different ways. Participants should understand how their words will be used. This approach treats personal accounts as valuable evidence without presenting every detail as an unquestionable fact.', mistakes: ['기억을 모두 정확한 사실로 취급하기', '기억의 차이를 이유로 경험 자료의 가치를 전부 부정하기'], rewrite: '자료를 교차 확인할 방법과 경험 자체를 이해할 방법을 따로 설명하세요.' },
  { topic: '학생의 시간제 일', prompt: 'Professor: Should universities encourage students to take part-time jobs during term?', passage: 'Ari: Work teaches practical skills and helps students pay expenses.\nBeth: Too many work hours can interfere with learning and rest.', checklist: ['학기 중 근무 장려에 대한 입장', '얻을 수 있는 기술의 사례', '학업과 휴식의 조건'], model: 'Universities should support suitable part-time work rather than encourage every student to work the same number of hours. A campus job can teach communication, reliability, and simple planning while helping with expenses. For example, working at a service desk gives a student practice explaining information clearly to different people. Yet Beth is right that the benefit can disappear if shifts repeatedly replace sleep or necessary study time. Universities could offer predictable schedules, limit expectations during examinations, and help students assess their own workload. They should also recognize that some students work from financial necessity, not preference. Advice is useful only when it responds to those circumstances instead of treating employment as an extra activity everyone can freely choose.', mistakes: ['일하는 시간을 학생이 항상 자유롭게 선택할 수 있다고 가정하기', '업무 경험을 얻는 것과 학습 효과를 자동 연결하기'], rewrite: '학업 부담이 큰 주간에 근무 계획을 조정할 방법을 제안하세요.' },
  { topic: '의무 봉사 활동', prompt: 'Professor: Should community service be a graduation requirement?', passage: 'Uma: A requirement introduces students to needs they might otherwise overlook.\nLeo: Compulsory hours can turn service into a task completed only for credit.', checklist: ['의무화에 대한 입장', '배움과 실제 기여의 관계', '단순 시간 채우기를 피할 조건'], model: 'I would offer structured community service as an option rather than a universal hour requirement. Uma is right that students can learn from needs outside their usual experience, but the community should gain useful support too. A student assigned to an unsuitable role may complete the hours without contributing much or understanding the work. Universities could connect interested students with organizations, explain responsibilities, and ask for a reflection on what was learned. Other practical learning routes should remain available for students with demanding work or care schedules. If a requirement is introduced, organizations need a say in the tasks and supervision. The value comes from a well-matched contribution, not simply from recording a number of hours.', mistakes: ['봉사 시간을 채우는 것을 지역사회 성과로 간주하기', '기관의 감독 부담을 고려하지 않기'], rewrite: '봉사자가 실제로 제공할 수 있는 도움과 기관이 원하는 도움의 일치 여부를 설명하세요.' },
  { topic: '동네 도서관의 역할', prompt: 'Professor: Should public libraries devote more space to community activities or protect quiet reading areas?', passage: 'Mae: Activities attract people who do not usually use a library.\nTheo: Quiet space is especially valuable for people without a peaceful place at home.', checklist: ['공간 배분에 관한 입장', '두 이용 목적의 차이 설명', '공존할 수 있는 구체적인 방식'], model: 'Libraries should provide both, but community activities need space and timing that protect quiet use. Mae is right that a workshop can bring new people into the building and help them discover other services. However, Theo’s concern is not just a preference for silence. A quiet desk may be someone’s only place to read, apply for a job, or prepare for an examination. An activity room near the entrance could serve groups while a separate area remains calm. When space is limited, the library could publish an activity schedule and avoid its busiest study periods. Decisions should reflect who currently depends on the building, including users who do not attend meetings or complete surveys.', mistakes: ['활동 참가자가 많으면 모든 공간을 바꿔도 된다고 쓰기', '조용한 공간의 이용자를 단순히 소음에 예민한 사람으로 설명하기'], rewrite: '공간을 분리하기 어려운 작은 도서관이라면 시간을 어떻게 나눌지 제안하세요.' },
  { topic: '소규모 상점의 온라인 서비스', prompt: 'Professor: Should local shops prioritize an online service or invest more in the in-person experience?', passage: 'Nia: Online information and ordering help shops reach customers with limited time.\nCole: Personal advice and a welcoming shop are what make local businesses distinctive.', checklist: ['투자 우선순위에 관한 입장', '고객이 겪는 구체적인 문제', '온라인과 현장 역할의 연결'], model: 'A local shop should first make basic information easy to find online, then build services that fit its customers. Someone may decide not to visit simply because opening hours or product availability are unclear. Accurate information and a simple way to ask a question can remove that problem without requiring a complicated ordering system. Cole is right that personal advice can be the shop’s strongest advantage, so the online service should help customers reach that experience rather than replace it. A repair shop, for example, could explain what to bring and offer appointment requests online. Before spending heavily, the owner should find out which customer difficulty is actually preventing visits or purchases.', mistakes: ['모든 업종에 같은 온라인 기능이 필요하다고 가정하기', '온라인 도입 자체를 매출 증가의 보장으로 쓰기'], rewrite: '선택한 상점의 실제 고객 문제에 맞춰 온라인 기능 하나를 구체화하세요.' },
  { topic: '제품 수리와 교체', prompt: 'Professor: Should consumers repair older products more often instead of replacing them?', passage: 'Yuna: Repair reduces waste and can preserve useful products.\nMark: Repair may be expensive, inconvenient, or unsuitable for a damaged product.', checklist: ['수리 우선 여부의 입장', '수리가 적절한 사례', '교체가 필요한 조건'], model: 'Consumers should consider repair before replacement when the product can be restored safely and used for a reasonable period. A loose part on a sturdy chair may be simple to fix, while buying a new chair creates expense and waste. Mark is right that repair is not automatically the better choice. The cost, expected life, and safety of the repaired item matter, and a qualified person may need to assess it. Manufacturers could help by making parts and clear repair information available. That would give consumers a real choice instead of leaving replacement as the only convenient option. The aim should be to extend useful life, not to keep every old product regardless of condition.', mistakes: ['모든 고장을 사용자가 직접 고칠 수 있다고 쓰기', '수리 비용과 안전 상태를 무시하기'], rewrite: '수리 판단에서 비교할 조건을 가격 외에 두 가지 더 제시하세요.' },
  { topic: '주차장과 녹지', prompt: 'Professor: A campus can turn part of a car park into a green sitting area. Is this a good priority?', passage: 'Soo: A green area would give people shade and a pleasant place between classes.\nWill: Removing parking could make access harder for commuters.', checklist: ['공간 전환에 대한 입장', '녹지의 구체적인 용도', '통학 접근 문제를 확인할 방법'], model: 'Turning part of the car park into a green area could improve campus life if the university first checks who uses the spaces. Shade and seating would help students spend short breaks outdoors, especially near buildings with few comfortable shared areas. Yet Will’s concern should influence the design. Some commuters may have limited alternatives, and accessible parking needs protection. The university could begin with a section that is often underused, improve nearby transport information, and monitor whether people lose practical access. It should explain the trade-off openly instead of presenting greenery as a benefit without a cost. A smaller, well-located area may provide more value than a large conversion that creates new problems.', mistakes: ['빈 시간대의 주차장만 보고 항상 비어 있다고 가정하기', '접근성 주차를 일반 주차와 동일하게 취급하기'], rewrite: '전환 전에 어떤 시간대의 이용 자료를 확인할지 써 보세요.' },
  { topic: '박물관 무료 입장', prompt: 'Professor: Should museums offer free entry to encourage wider participation?', passage: 'Alia: Removing ticket costs makes cultural experiences available to more people.\nTom: Museums need reliable income to care for collections and provide services.', checklist: ['무료 입장 범위에 관한 입장', '접근 비용과 운영 비용의 관계', '지속 가능한 지원 방식'], model: 'Museums should offer regular opportunities for free entry while making sure the funding supports good services. Alia is right that ticket prices can stop a family from visiting, especially if members are unsure whether the museum will interest them. A free day or a clear support scheme could lower that barrier. However, Tom’s concern matters because a poorly maintained or understaffed museum is not truly accessible. Public funding, donations, or paid special programs might help cover costs, depending on the institution. Museums should also consider transport, opening hours, and understandable information. A zero ticket price helps, but wider participation requires people to be able to reach the building and feel welcome once inside.', mistakes: ['입장료만 없애면 모든 접근 장벽이 사라진다고 쓰기', '운영 비용을 고려하지 않고 무료화를 주장하기'], rewrite: '입장료 외에 방문을 어렵게 만드는 요인 하나와 해결책을 추가하세요.' },
  { topic: '여러 언어의 학습 자료', prompt: 'Professor: Should universities provide some introductory course materials in several languages?', passage: 'Mei: Extra language support helps students understand unfamiliar concepts.\nCaleb: Students also need practice using the course’s main language.', checklist: ['다언어 지원의 역할에 관한 입장', '개념 이해를 돕는 구체적 자료', '주 수업 언어 연습과의 연결'], model: 'Selected materials in several languages can help students build understanding without replacing practice in the main course language. A short glossary, for example, lets a student connect a new technical term with a concept already understood. After that, the student can use the term in a discussion or explain it in their own words. Caleb is right that full dependence on translation could limit practice, but that is an argument for thoughtful support rather than no support. Teachers could provide key terms and brief explanations while keeping activities in the main language. The translations should be checked for accuracy, and students should know when a word has a specialized meaning that differs from everyday use.', mistakes: ['번역을 제공하면 주 수업 언어 학습이 반드시 약해진다고 단정하기', '기계 번역의 전문 용어를 검토 없이 정확하다고 취급하기'], rewrite: '번역 지원을 사용한 다음 주 언어로 수행할 활동을 하나 제안하세요.' },
  { topic: '가상 견학과 현장 방문', prompt: 'Professor: Can virtual visits replace field trips in education?', passage: 'Seth: Virtual visits cost less and let students explore distant places.\nRae: A real visit includes direct observation and unexpected questions.', checklist: ['대체 가능한 범위의 입장', '가상 방문과 실제 관찰의 차이', '학습 목적에 맞는 선택'], model: 'Virtual visits can replace some travel, but they should be chosen according to the learning goal. If a class wants to compare buildings in several countries, an online tour may provide a range of examples that would otherwise be impossible to see. A real visit is more useful when students need to observe how a place works, such as where people pause or how a route feels to walk. Rae’s point about unexpected questions is important because a prepared tour selects what the viewer sees. Teachers could use a virtual visit to prepare questions before a nearby field trip. Students would then arrive with a purpose while still being encouraged to notice things that the recording left out.', mistakes: ['화면으로 보는 것과 현장 경험을 완전히 동일하다고 쓰기', '비용이 낮다는 이유만으로 학습 효과를 판단하기'], rewrite: '가상 자료로 충분한 활동과 직접 관찰이 필요한 활동을 각각 하나 쓰세요.' },
  { topic: '기초 금융 교육', prompt: 'Professor: Should all first-year students take a short course on managing personal finances?', passage: 'Jin: Basic budgeting skills are useful whatever students study.\nClara: A required course may be too general for students with very different circumstances.', checklist: ['금융 교육 제공 방식의 입장', '실생활에서 필요한 기술 예', '학생 상황 차이에 대한 대응'], model: 'A short practical introduction would be useful if it focuses on decisions students actually face. Comparing payment options, reading a bill, and planning for irregular expenses can help students in many subjects. However, Clara is right that one budget example may not reflect someone who supports family members or has an unpredictable income. The course should offer different cases and avoid implying that every financial problem results from poor planning. Students could choose exercises relevant to their situation and learn where to get reliable individual help. This would provide a common starting point without pretending to solve every difficulty. The content should be updated and clearly separated from advertisements for particular financial products.', mistakes: ['경제적 어려움을 모두 개인의 계획 부족으로 설명하기', '특정 금융 상품을 교육의 정답으로 제시하기'], rewrite: '소득이나 책임이 다른 학생 두 명에게 같은 수업이 어떻게 적용되는지 설명하세요.' },
  { topic: '관객 참여형 예술', prompt: 'Professor: Does inviting audience participation make an exhibition better?', passage: 'Dara: Participation makes visitors active contributors rather than passive viewers.\nHugo: Some works need quiet attention, and participation can distract from them.', checklist: ['참여 방식의 가치에 관한 입장', '작품 이해에 도움이 되는 참여 예', '참여하지 않을 선택 존중'], model: 'Audience participation improves an exhibition when it helps visitors engage with the work’s purpose. For an exhibition about neighborhood change, visitors might add memories to a shared map and compare different experiences. That contribution can extend the discussion beyond the artist’s own viewpoint. Hugo is right, though, that asking people to interact with everything may interrupt careful looking. A quiet painting does not become better merely because a button is added beside it. Participation should be optional and clearly connected to the work. The display also needs a way to manage contributions so that one visitor does not dominate the experience. Thoughtful participation offers another route into the exhibition while preserving space for observation.', mistakes: ['버튼이나 활동이 있으면 작품 이해가 자동으로 깊어진다고 쓰기', '참여를 원하지 않는 관객을 소극적이라고 단정하기'], rewrite: '참여 활동이 작품의 주제와 연결되는 과정을 구체적인 예로 보여 주세요.' },
  { topic: '첫 직장의 선택', prompt: 'Professor: For a first job, should graduates prioritize a high salary or opportunities to learn?', passage: 'Milo: Learning early can create more choices later in a career.\nFaye: Graduates may need stable income to meet immediate responsibilities.', checklist: ['직장 선택 기준의 입장', '학습 기회의 실제 내용', '즉각적인 재정 책임 고려'], model: 'Graduates should compare the whole position rather than choose between salary and learning as if only one mattered. Milo is right that useful training and constructive supervision can open later opportunities. However, a promise of learning is not enough; the employer should explain what support is actually available. Faye’s point also matters for a graduate who has immediate financial responsibilities. A reasonable salary with dependable hours may make it possible to learn well, while very long hours can limit both development and daily life. I would look for concrete evidence of training, manageable expectations, and enough income for essential needs. The best balance will differ between graduates, so advice should leave room for their circumstances.', mistakes: ['학습 기회를 이유로 낮은 보수를 항상 정당화하기', '모든 졸업생이 같은 재정 상황이라고 가정하기'], rewrite: '구인 공고에서 실제로 확인해야 할 학습 지원의 증거를 한 가지 제시하세요.' },
  { topic: '시민 참여 조사', prompt: 'Professor: Should researchers involve local residents in collecting information about their communities?', passage: 'Jules: Residents know places and issues that outside researchers may miss.\nAna: Collection methods must be consistent for the information to be useful.', checklist: ['주민 참여의 역할에 관한 입장', '지역 지식이 돕는 사례', '기록 방법과 품질 확인 조건'], model: 'Residents can make a valuable contribution if the project provides clear methods and listens to their local knowledge. Someone who uses a street every day may notice a difficult crossing or a recurring problem that a short professional visit misses. Ana is right that the information still needs to be comparable. Participants should learn what to record, how to describe uncertainty, and where to report a problem with the method. A simple form with a few shared examples could help, while researchers check a selection of records and explain how the findings will be used. Residents should also help shape the questions. Their role should be more than supplying unpaid observations for a study they never hear about again.', mistakes: ['지역 경험만으로 모든 기록이 정확하다고 가정하기', '주민에게 결과를 돌려주는 과정을 생략하기'], rewrite: '참가자가 같은 방식으로 기록할 수 있도록 안내할 규칙을 하나 만들어 보세요.' },
  { topic: '화면 없는 수업 시간', prompt: 'Professor: Should courses regularly include activities without screens?', passage: 'Tariq: Screen-free activities encourage discussion and help students notice their surroundings.\nElsa: Digital tools can support access and make collaboration easier.', checklist: ['화면 없는 활동의 범위', '활동 목적을 보여 주는 사례', '필요한 지원 도구와의 공존'], model: 'Courses should include screen-free activities when they offer a useful change in how students work. A brief discussion in pairs, for instance, may help students test an explanation without spending the whole time arranging slides. Observing a nearby space with a notebook can also direct attention to details that are easy to overlook behind a screen. Elsa is right that some students need digital tools to participate, so the activity should not become a rigid ban. The instructor can explain the purpose and allow suitable support. What matters is whether students think and communicate more effectively during that task. Alternating methods is more useful than treating either paper or technology as automatically superior.', mistakes: ['디지털 접근성 도구를 모두 제거하기', '화면이 없다는 사실만으로 집중이 보장된다고 쓰기'], rewrite: '화면 없이 하는 활동의 목표를 도구 이름 없이 한 문장으로 설명하세요.' },
  { topic: '유연한 식사권', prompt: 'Professor: Should campus meal plans allow students to use credits at different times and locations?', passage: 'Bea: Flexibility helps students with changing timetables and reduces missed meals.\nAsher: Too many options can make the service harder to manage and more expensive.', checklist: ['식사권 유연성의 입장', '불규칙한 시간표의 사례', '운영의 한계를 고려한 방안'], model: 'Meal plans should offer some flexibility because student schedules do not always match one cafeteria’s hours. A student returning from a late practical class may miss a meal already paid for, even though another campus outlet is still open. Allowing credits at a few participating locations could solve that problem. Asher is right that an unlimited system would be difficult to run, so the university could begin with clear options and published limits. Students should be able to see where and when credits work before buying the plan. The university should also compare whether the change reduces missed meals without creating excessive costs. Flexibility is useful when it responds to a real access problem, not when it adds confusing rules.', mistakes: ['모든 매장에서 모든 시간에 사용할 수 있어야 한다고 가정하기', '구매 전에 이용 조건을 알 필요를 빠뜨리기'], rewrite: '식사권을 사용할 수 있는 조건을 학생이 쉽게 확인하는 방법을 제안하세요.' },
  { topic: '신입생의 폭넓은 수업', prompt: 'Professor: Should first-year students take courses outside their intended major?', passage: 'Kira: Trying unfamiliar subjects can reveal interests and build useful connections.\nDean: Students may want to focus early and avoid extra requirements.', checklist: ['전공 밖 수업에 관한 입장', '다른 분야가 도움이 되는 구체적인 예', '시간과 졸업 요건에 대한 고려'], model: 'First-year students should have room to try a small number of courses outside their major. A student planning to study engineering might discover that a design or communication class helps explain ideas to people who will use a product. The experience can also confirm an interest instead of forcing a change of direction. Dean’s concern is reasonable if exploration adds costs or delays required courses. Universities should make the options count toward existing requirements and offer clear advice about workload. Students do not need to sample everything. One carefully chosen unfamiliar course can broaden the questions they ask while allowing them to keep moving through the main program they have chosen.', mistakes: ['모든 분야를 경험해야 한다고 요구하기', '추가 수업이 학위 일정과 비용에 미치는 영향을 무시하기'], rewrite: '자신의 전공과 연결될 수 있는 다른 분야 수업을 구체적인 이유와 함께 선택하세요.' },
  { topic: '대중교통의 접근성', prompt: 'Professor: Should cities prioritize making existing bus routes accessible or adding new routes?', passage: 'Sami: An existing route is not useful to everyone if stops and vehicles are difficult to use.\nLuca: Residents in unserved areas need routes before other improvements can help them.', checklist: ['투자 우선순위의 입장', '이동의 전체 과정을 고려한 사례', '미서비스 지역과의 균형'], model: 'Cities should identify where an improvement would remove the largest practical barrier, rather than assume that new routes or accessibility always come first. Sami is right that a bus passing nearby is not enough if someone cannot reach the stop or board safely. Improving that journey could make an existing service useful to many more people. Luca’s point matters where no route is available at all. The city should compare both situations using information from residents, including people who currently cannot travel and therefore do not appear in passenger counts. A combination of targeted stop improvements and carefully chosen new connections may offer more benefit than expanding a network that some residents still cannot use.', mistakes: ['현재 승객 수만으로 이용하지 못하는 사람의 수요를 판단하기', '정류장 도착·승차·하차를 분리해서 접근 문제를 놓치기'], rewrite: '집에서 목적지까지 이동할 때 한 단계의 어려움이 전체 여정을 막는 예를 쓰세요.' },
]

export const coachedWritingItems = [
  ...emails.map((data, index) => writingItem(data, 'email', index)),
  ...discussions.map((data, index) => writingItem(data, 'discussion', index)),
]
